import type { MetadataRoute } from "next";
import { PROJECTS } from "@/content";

/**
 * /sitemap.xml — auto-generated by Next.js from this route.
 *
 * The home page is the highest-priority entry, followed by the four
 * project deep-dives. Dev kit is `noindex` so it doesn't appear in
 * search results.
 */

// Canonical site URL. Read from env at build time; fall back to the
// GitHub-Pages-style origin for local dev. `||` (not `??`) so an
// empty string in .env.local still falls back instead of being treated
// as a configured value.
const SITE_URL =
  process.env.NEXT_PUBLIC_SITE_URL?.replace(/\/$/, "") ||
  "https://darkeye-portfolio.example.com";

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date();
  return [
    {
      url: `${SITE_URL}/`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 1.0,
    },
    ...PROJECTS.items.map((project) => ({
      url: `${SITE_URL}/projects/${project.id}`,
      lastModified: now,
      changeFrequency: "monthly" as const,
      priority: 0.8,
    })),
  ];
}
